//! Schema freshness check for the Messaging Profile schema set.
//!
//! The files in `v1.0/dsip-messaging-schemas-draft/schemas/` are generated by
//! `generate_schemas.py` beside them. This script regenerates them into a scratch directory and
//! fails the build if the committed files differ, as `dsip-schema` does for the core set.
//! If `python3` is unavailable the check is skipped with a warning.

use std::path::{Path, PathBuf};
use std::process::Command;

/// The root of the DSIP repository, which holds `v1.0/` and `impl/vectors`: `DSIP_SPEC` if set, else this
/// workspace's own (in DSIP, `impl/` sits in it) or its `spec/` submodule (in dsip-rs).
fn spec_root() -> PathBuf {
    if let Ok(root) = std::env::var("DSIP_SPEC") {
        return PathBuf::from(root);
    }
    let manifest = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("manifest dir"));
    [manifest.join("../../.."), manifest.join("../../spec")]
        .into_iter()
        .find(|root| root.join("v1.0").is_dir())
        .expect("the DSIP spec: set DSIP_SPEC, or check out the spec/ submodule")
        .canonicalize()
        .expect("spec root")
}

fn schema_dir(root: &Path) -> PathBuf {
    root.join("v1.0/dsip-messaging-schemas-draft")
}

fn main() {
    let root = spec_root();
    println!("cargo:rerun-if-env-changed=DSIP_SPEC");
    println!("cargo:rustc-env=DSIP_SPEC={}", root.display());
    let dir = schema_dir(&root);
    let schemas = dir.join("schemas");
    println!("cargo:rerun-if-changed={}", schemas.display());
    println!("cargo:rerun-if-changed={}", dir.join("generate_schemas.py").display());
    for entry in std::fs::read_dir(&schemas).expect("schema dir exists") {
        println!("cargo:rerun-if-changed={}", entry.expect("entry").path().display());
    }
    let out = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR")).join("regen");
    // A schema removed from the generator must not survive in the scratch output of an earlier build.
    let _ = std::fs::remove_dir_all(&out);
    let status = Command::new("python3").arg(dir.join("generate_schemas.py")).arg(&out).status();
    match status {
        Ok(s) if s.success() => compare(&schemas, &out),
        _ => println!("cargo:warning=python3 unavailable; messaging schema freshness check skipped"),
    }
}

fn compare(committed: &Path, regenerated: &Path) {
    let mut drift = vec![];
    for entry in std::fs::read_dir(regenerated).expect("regen dir") {
        let p = entry.expect("entry").path();
        let name = p.file_name().expect("name").to_owned();
        let a = std::fs::read(&p).expect("read regen");
        let b = std::fs::read(committed.join(&name)).unwrap_or_default();
        if a != b {
            drift.push(name.to_string_lossy().into_owned());
        }
    }
    if !drift.is_empty() {
        panic!(
            "messaging schema drift: committed schemas differ from generate_schemas.py output for {:?}. \
             Regenerate with `python3 v1.0/dsip-messaging-schemas-draft/generate_schemas.py v1.0/dsip-messaging-schemas-draft/schemas`.",
            drift
        );
    }
}
